@pytest.mark.parametrize("closed", [(0,), (1,), (2,), (0, 1), (0, 2), (1, 2), (0, 1, 2)]) def test_review_worker_captures_with_closed_standard_streams(tmp_path, closed): # Real subprocess: closing pytest's own streams would invalidate the instrument. root = Path(os.environ.get("DIAGNOSTIC_EVIDENCE", tmp_path / "receipts")) root.mkdir(parents=True, exist_ok=True) target = root / f"worker-closed-stdio-{''.join(map(str, closed))}-{time.time_ns()}.json" code = """ import json, os, sys, time from dataclasses import asdict from pathlib import Path from worker_capture import capture_helper for fd in map(int, sys.argv[2:]): os.close(fd) receipt = capture_helper((sys.executable, '-c', "print('stdio-ok')"), time.monotonic() + 1) data = asdict(receipt) data.update(stdout=receipt.stdout.hex(), stderr=receipt.stderr.hex(), controller_pid=os.getpid()) Path(sys.argv[1]).write_text(json.dumps(data, indent=2)) """ check = subprocess.run( [sys.executable, "-c", code, str(target), *map(str, closed)], capture_output=True, timeout=3, ) assert check.returncode == 0, check.stderr receipt = json.loads(target.read_text()) > assert receipt["error"] is None E AssertionError: assert 'worker capture failed: incomplete worker publication' is None
